package main

import (
	"database/sql"
	"fmt"
	"net/http"
	"os"
	"strings"

	_ "github.com/lib/pq"
)

var db *sql.DB

func init() {
	var err error
	connStr := os.Getenv("DATABASE_URL")
	db, err = sql.Open("postgres", connStr)
	if err != nil {
		panic(err)
	}
}

// sanitizeInput performs basic input cleaning
func sanitizeInput(input string) string {
	// Remove null bytes and trim whitespace
	input = strings.ReplaceAll(input, "\x00", "")
	input = strings.TrimSpace(input)
	return input
}

// validateCategory checks category against known values
func validateCategory(cat string) bool {
	valid := []string{"electronics", "books", "clothing", "food", "toys"}
	for _, v := range valid {
		if strings.EqualFold(cat, v) {
			return true
		}
	}
	return false
}

func searchProducts(w http.ResponseWriter, r *http.Request) {
	category := sanitizeInput(r.URL.Query().Get("category"))
	sortBy := sanitizeInput(r.URL.Query().Get("sort"))
	priceRange := sanitizeInput(r.URL.Query().Get("price_range"))

	if category == "" {
		http.Error(w, "category required", http.StatusBadRequest)
		return
	}

	if !validateCategory(category) {
		http.Error(w, "invalid category", http.StatusBadRequest)
		return
	}

	// Build query - category is validated, sort and price_range are user-controlled
	query := fmt.Sprintf(
		"SELECT id, name, price, description FROM products WHERE category = '%s'",
		category,
	)

	if priceRange != "" {
		// Expected format: "10-50" but not validated beyond sanitizeInput
		parts := strings.Split(priceRange, "-")
		if len(parts) == 2 {
			query += fmt.Sprintf(" AND price BETWEEN %s AND %s", parts[0], parts[1])
		}
	}

	if sortBy != "" {
		// Sort parameter directly interpolated into ORDER BY
		query += fmt.Sprintf(" ORDER BY %s", sortBy)
	}

	rows, err := db.Query(query)
	if err != nil {
		http.Error(w, "query error", http.StatusInternalServerError)
		return
	}
	defer rows.Close()

	w.Header().Set("Content-Type", "text/plain")
	for rows.Next() {
		var id int
		var name, description string
		var price float64
		if err := rows.Scan(&id, &name, &price, &description); err != nil {
			continue
		}
		fmt.Fprintf(w, "%d | %s | %.2f | %s\n", id, name, price, description)
	}
}

func healthCheck(w http.ResponseWriter, r *http.Request) {
	err := db.Ping()
	if err != nil {
		http.Error(w, "unhealthy", http.StatusServiceUnavailable)
		return
	}
	w.Write([]byte("ok"))
}

func main() {
	http.HandleFunc("/api/products/search", searchProducts)
	http.HandleFunc("/health", healthCheck)
	http.ListenAndServe(":8080", nil)
}
